import type OpenFin from '@openfin/core';

import { createInlineDebugLogger } from '@common/utils/debug-log';
import { findPageForView } from '@common/utils/layout';
import { currentOFIdentity } from '@common/utils/window';

import { selectPage } from '@enterprise/slices/pages/attached';

import { getState } from './state';

const debug = createInlineDebugLogger('getLayoutContainerKeyForView');

/**
 * Resolves the layout container DOM id for a view attached to this browser window.
 * Window-level view events do not include layout identity; this matches the store page for the view.
 */
export const getLayoutContainerKeyForView = async (viewIdentity: OpenFin.Identity): Promise<string | undefined> => {
    const view = fin.View.wrapSync(viewIdentity);

    let win: OpenFin.Window;
    try {
        win = await view.getCurrentWindow();
    } catch {
        debug('view already destroyed or detached, cannot resolve window', { viewName: viewIdentity.name });
        return;
    }

    if (win.identity.name !== currentOFIdentity.name) {
        debug('view belongs to a different window', { viewName: viewIdentity.name, windowName: win.identity.name });
        return;
    }
    const page = await findPageForView(viewIdentity.name, currentOFIdentity);
    if (!page) {
        debug('no page found for view', { viewName: viewIdentity.name });
        return;
    }
    const storedPage = selectPage(getState(), page.pageId);
    debug('resolved', { viewName: viewIdentity.name, layoutContainerKey: storedPage?.layoutContainerKey });
    return storedPage?.layoutContainerKey;
};
