import type OpenFin from '@openfin/core';

import { mapContentComponentState } from '@common/utils/layout';

import { AttachedPageInternal } from '@common/api/pages/shapes';

export interface PagesLayoutSnapshot {
    layouts: {
        [layoutContainerKey: string]: OpenFin.LayoutOptions;
    };
    pages: AttachedPageInternal[];
}

type LayoutsByName = OpenFin.LayoutSnapshot['layouts'];

/*
 * Because the view names are ephemeral and new view name is generated once the snapshot is applied
 * we need to reset it to the new view name for pages that contain only single view.
 * If we don't do that singleViewName would be outdated name from the previous session.
 */
const updatePageForSingleViewName = (page: AttachedPageInternal): AttachedPageInternal => {
    const layout = page.layout;
    const componentStates = layout.content ? mapContentComponentState(layout.content) : [];
    const viewCount = componentStates.length;

    if (viewCount > 1) {
        return { ...page, singleViewName: null };
    } else if (viewCount === 1) {
        return { ...page, singleViewName: componentStates[0].name };
    }
};

export const convertPagesToLayoutSnapshot = (pages: AttachedPageInternal[], isEnterprise: boolean) => {
    const layouts: LayoutsByName = pages.reduce((acc: LayoutsByName, page: AttachedPageInternal) => {
        if (!page.isActive) {
            if (!isEnterprise) {
                // Remove all the pages except the active one so others can be lazy loaded
                return acc;
            }
            const singleViewPageCheck = updatePageForSingleViewName(page);
            if (!singleViewPageCheck.singleViewName) {
                // In EB, only remove the page if it has more than one view so the Supertab title shows up
                return acc;
            }
        }
        acc[page.layoutContainerKey] = page.layout;
        return acc;
    }, {} as LayoutsByName);
    return { layouts, pages: pages };
};

export const convertLayoutSnapshotToPages = ({ pages, layouts }: PagesLayoutSnapshot): AttachedPageInternal[] => {
    return pages
        .map((x) => ({ ...x, layout: layouts[x.layoutContainerKey] || x.layout } as AttachedPageInternal))
        .map(updatePageForSingleViewName);
};
