import { useEffect } from 'react';
import { useDispatch } from 'react-redux';

import type OpenFin from '@openfin/core';

import { finUUID } from '@common/utils/env';
import { menuEvents } from '@common/utils/menu-window-provider';
import { WindowName } from '@common/utils/window';

import { closeModal, openModal } from '@common/slices/modal';

import { FOCUS_DEBOUNCE_MS } from '@common/types/focus';

const isModalWindowRequiringFocusHandling = (identity: OpenFin.Identity): boolean => {
    return (
        !identity.name.startsWith(WindowName.BrowserAddressSearchPrefix) &&
        identity.name !== WindowName.ZoomControlsDialog &&
        // Custom context menu and dropdown menu are non-blocking transient UI elements
        // They should not add focus blockers as they close automatically on blur
        identity.name !== WindowName.DropdownMenu &&
        identity.name !== WindowName.EnterpriseContextMenu &&
        // Tab search menu switches pages on return to the browser window, no need to refocus view on the current page
        identity.name !== WindowName.TabSearchMenu &&
        ['menu', 'modal', 'dialog'].some((prefix) => identity.name.includes(prefix))
    );
};

/**
 * Syncs modal window state to Redux store.
 * - Opens are tracked via shared emitter (emitted before window shows for precise timing)
 * - Closes are tracked via app-level window-hidden/closed events
 */
export const useModalEventSync = (): void => {
    const dispatch = useDispatch();

    useEffect(() => {
        const app = fin.Application.getCurrentSync();

        const handleModalOpened = (name: string) => {
            if (!isModalWindowRequiringFocusHandling({ name, uuid: finUUID })) {
                return;
            }
            // Small delay to allow view focus to establish before modal blocker is added
            // This ensures find-in-page and other view-focused features can appear during modal transitions
            setTimeout(() => {
                dispatch(openModal(name));
            }, FOCUS_DEBOUNCE_MS);
        };

        const handleWindowHidden = (payload: OpenFin.ApplicationEvents.ByType<'window-hidden' | 'window-closed'>) => {
            if (isModalWindowRequiringFocusHandling(payload)) {
                dispatch(closeModal(payload.name));
            }
        };

        menuEvents.addListener('modal-opened', handleModalOpened);
        app.on('window-hidden', handleWindowHidden);
        app.on('window-closed', handleWindowHidden);

        return () => {
            menuEvents.removeListener('modal-opened', handleModalOpened);
            app.removeListener('window-hidden', handleWindowHidden);
            app.removeListener('window-closed', handleWindowHidden);
        };
    }, [dispatch]);
};
